import { ShapeOptionsBase, ConnectionOptionsBase } from './types';
/**
 * Defines a mapping specification that can either be a property path string or a function.
 *
 * Used to extract values from source objects in data mapping operations. When a string is provided,
 * it represents a dot-notation path to a property (e.g., "user.name"). When a function is provided,
 * it receives the input object and should return the desired value.
 *
 * @template TInput - The type of the input object
 * @template TValue - The type of the value to be extracted
 *
 * @example
 * ```typescript
 * // Using property path
 * const pathMapping: FromPathOrFn<User, string> = 'profile.name';
 *
 * // Using function
 * const fnMapping: FromPathOrFn<User, string> = (user) => `${user.firstName} ${user.lastName}`;
 * ```
 */
export type FromPathOrFn<TInput, TValue> = string | ((input: TInput) => TValue);
/**
 * Defines a mapping specification object that maps target object properties to source extraction rules.
 *
 * Each property in the target type can be mapped using either a property path string or a function
 * that extracts the value from the source object. This allows flexible transformation of data
 * from one structure to another.
 *
 * @template TSrc - The type of the source object being mapped from
 * @template TTarget - The type of the target object being mapped to
 *
 * @example
 * ```typescript
 * interface Person { name: string; age: number; }
 * interface User { id: string; fullName: string; }
 *
 * const mapping: MapSpec<User, Person> = {
 *   name: 'fullName',           // Direct property mapping
 *   age: (user) => user.age || 0 // Function-based mapping with default
 * };
 * ```
 */
export type MapSpec<TSrc, TTarget> = {
    [K in keyof TTarget]?: FromPathOrFn<TSrc, TTarget[K]>;
};
/**
 * Configuration for mapping source data to diagram shapes.
 *
 * Defines how to extract shape data from the input and how to transform each shape
 * from the source format to the required ShapeOptions format. The source specifies
 * where to find the array of shape data, and the map defines the field mappings.
 *
 * @template TShapeSrc - The type of individual shape objects in the source data
 *
 * @example
 * ```typescript
 * const shapeMapping: ShapeMapping<NodeData> = {
 *   source: 'nodes',  // Extract from input.nodes array
 *   map: {
 *     id: 'nodeId',
 *     x: 'position.x',
 *     y: 'position.y',
 *     content: (node) => ({ text: node.label })
 *   }
 * };
 * ```
 */
export type ShapeMapping<TShapeSrc = any> = {
    source: FromPathOrFn<any, TShapeSrc[]>;
    map: MapSpec<TShapeSrc, ShapeOptionsBase>;
};
/**
 * Configuration for mapping source data to diagram connections.
 *
 * Defines how to extract connection data from the input and how to transform each connection
 * from the source format to the required ConnectionOptions format. The source specifies
 * where to find the array of connection data, and the map defines the field mappings.
 *
 * @template TConnSrc - The type of individual connection objects in the source data
 *
 * @example
 * ```typescript
 * const connectionMapping: ConnectionMapping<LinkData> = {
 *   source: 'links',  // Extract from input.links array
 *   map: {
 *     from: 'sourceId',
 *     to: 'targetId',
 *     stroke: (link) => ({ color: link.color, width: link.thickness })
 *   }
 * };
 * ```
 */
export type ConnectionMapping<TConnSrc = any> = {
    source: FromPathOrFn<any, TConnSrc[]>;
    map: MapSpec<TConnSrc, ConnectionOptionsBase>;
};
/**
 * Complete mapping configuration for converting input data to diagram model.
 *
 * Contains both shape and connection mapping configurations that define how to
 * extract and transform data from the input object into the format required
 * for diagram rendering.
 *
 * @example
 * ```typescript
 * const diagramMapping: DiagramMapping = {
 *   shapes: {
 *     source: 'orgChart.employees',
 *     map: {
 *       id: 'empId',
 *       content: (emp) => ({ text: emp.name, image: emp.photo }),
 *       x: 'position.x',
 *       y: 'position.y'
 *     }
 *   },
 *   connections: {
 *     source: 'orgChart.relationships',
 *     map: {
 *       from: 'managerId',
 *       to: 'employeeId'
 *     }
 *   }
 * };
 * ```
 *
 */
export interface DiagramMapping {
    shapes: ShapeMapping<any>;
    connections: ConnectionMapping<any>;
}
/**
 * Result object returned by the diagram data conversion process.
 *
 * Contains the converted shapes and connections arrays that are ready to be used
 * for diagram rendering. Each array contains properly formatted options objects
 * that conform to the diagram component's expected data structure.
 *
 * @example
 * ```typescript
 * const result: ConvertResult = {
 *   shapes: [
 *     { id: '1', x: 100, y: 100, content: { text: 'Node 1' } },
 *     { id: '2', x: 200, y: 100, content: { text: 'Node 2' } }
 *   ],
 *   connections: [
 *     { from: '1', to: '2' }
 *   ]
 * };
 * ```
 *
 */
export interface ConvertResult {
    shapes: ShapeOptionsBase[];
    connections: ConnectionOptionsBase[];
}
/**
 * Converts input data to diagram model format using the provided mapping configuration.
 *
 * This function takes raw input data and transforms it into a structured diagram model
 * containing shapes and connections arrays. It uses the mapping configuration to
 * extract data from the input and apply field mappings to create properly formatted
 * ShapeOptions and ConnectionOptions objects.
 *
 * @param input - The raw input data object containing source data for shapes and connections
 * @param mapping - Configuration object defining how to extract and map data from input
 * @param mapping.shapes - Shape mapping configuration with source path and field mappings
 * @param mapping.connections - Connection mapping configuration with source path and field mappings
 * @returns An object containing arrays of mapped shapes and connections ready for diagram rendering
 *
 * @example
 * ```typescript
 * const input = {
 *   items: [{ id: '1', name: 'Node 1', x: 100, y: 100 }],
 *   links: [{ from: '1', to: '2' }]
 * };
 *
 * const mapping = {
 *   shapes: {
 *     source: 'items',
 *     map: { id: 'id', content: 'name', x: 'x', y: 'y' }
 *   },
 *   connections: {
 *     source: 'links',
 *     map: { from: 'from', to: 'to' }
 *   }
 * };
 *
 * const result = convertToDiagramModel(input, mapping);
 * // Returns: { shapes: [...], connections: [...] }
 * ```
 *
 */
export declare const convertToDiagramModel: (input: any, mapping: DiagramMapping) => ConvertResult;
